CREATE TABLE habitaciones (id BIGSERIAL PRIMARY KEY, numero VARCHAR(20) NOT NULL UNIQUE, sector VARCHAR(100) NOT NULL, piso INTEGER NOT NULL, estado VARCHAR(20) NOT NULL DEFAULT 'ACTIVA');
CREATE TABLE camas (id BIGSERIAL PRIMARY KEY, numero VARCHAR(20) NOT NULL, habitacion_id BIGINT NOT NULL, estado VARCHAR(20) NOT NULL DEFAULT 'DISPONIBLE', CONSTRAINT fk_camas_habitacion FOREIGN KEY (habitacion_id) REFERENCES habitaciones(id), CONSTRAINT uk_cama_habitacion UNIQUE(habitacion_id,numero), CONSTRAINT ck_camas_estado CHECK(estado IN ('DISPONIBLE','OCUPADA','MANTENIMIENTO')));
CREATE TABLE internaciones (id BIGSERIAL PRIMARY KEY,paciente_id BIGINT NOT NULL,profesional_id BIGINT NOT NULL,fecha_ingreso TIMESTAMP NOT NULL,fecha_alta TIMESTAMP,motivo_internacion VARCHAR(500) NOT NULL,diagnostico_ingreso VARCHAR(3000),estado VARCHAR(20) NOT NULL DEFAULT 'ACTIVA',cama_id BIGINT NOT NULL,admision_id BIGINT,CONSTRAINT fk_int_paciente FOREIGN KEY(paciente_id) REFERENCES pacientes(id),CONSTRAINT fk_int_prof FOREIGN KEY(profesional_id) REFERENCES profesionales(id),CONSTRAINT fk_int_cama FOREIGN KEY(cama_id) REFERENCES camas(id),CONSTRAINT fk_int_admision FOREIGN KEY(admision_id) REFERENCES admisiones(id),CONSTRAINT ck_int_estado CHECK(estado IN ('ACTIVA','ALTA_MEDICA','CANCELADA')));
CREATE TABLE observaciones_enfermeria (id BIGSERIAL PRIMARY KEY,internacion_id BIGINT NOT NULL,enfermero_id BIGINT NOT NULL,fecha_hora TIMESTAMP NOT NULL,descripcion VARCHAR(3000) NOT NULL,tipo VARCHAR(30) NOT NULL,autor VARCHAR(100) NOT NULL,CONSTRAINT fk_obs_int FOREIGN KEY(internacion_id) REFERENCES internaciones(id),CONSTRAINT ck_obs_tipo CHECK(tipo IN ('OBSERVACION_GENERAL','CONTROL','INCIDENCIA')));
CREATE INDEX idx_internaciones_paciente_estado ON internaciones(paciente_id,estado);
